WITH category_node AS (
    SELECT id FROM sys_category WHERE app_code = 'youanshang' AND type = 'knowledge_point' AND code = 'kp_age_a_change_people'
)
INSERT INTO sys_content (app_code, title, slug, content_json, content_html, summary, category_id, tags, is_pinned, is_public, is_published, publish_time, view_count, sort_order, extra, created_by, created_time)
SELECT 'gongkao', '增减人平均变化', 'kp-age-a-change-people', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "增减人导致平均年龄变化"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心定义：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "老人走、新人来，导致平均数拉升或下降。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、题型定义与识别"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "“原 5 人平均 30 岁。走了一个人，来了一个 20 岁的人，平均年龄变成了 28 岁。问走的那个人多大？”"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、核心法则（盈亏思想）"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "可以直接算总和再相减，也可以用更高级的【盈亏法】："}]}, {"type": "paragraph", "content": [{"type": "text", "text": "平均年龄降了 2 岁（30变28）。说明整个盘子亏了 5人×2岁 = 10 岁。新来的 20 岁，比走的那个少了 10 岁。所以走的是 30 岁！"}]}]}$$ AS jsonb), NULL, '增减人平均变化的核心考点与实战推导。', category_node.id, CAST('["数量关系", "年龄问题", "增减人平均变化"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_age_a_change_people", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
